dragging = true;
startX = evt.getX();
// Remember starting position.
startY = evt.getY();
prevX = startX;
// Remember most recent coords.
prevY = startY;
.
. // Other processing.
.
}
}
public void mouseDragged(MouseEvent evt) {
if ( dragging == false )
// First, check if we are
return;
