if ( root != null ) {
// (Otherwise, there’s nothing to print.)
postorderPrint( root.left );
// Print items in left subtree.
postorderPrint( root.right );
// Print items in right subtree.
System.out.print( root.item + " " );
// Print the root item.
}
} // end postorderPrint()
